type BookingDropdownOption={value:string;label:string};
function BookingDropdown({id,label,value,options,onChange}:{id:string;label:string;value:string;options:BookingDropdownOption[];onChange:(value:string)=>void}){
 const [open,setOpen]=useState(false),[focused,setFocused]=useState(0);
 const root=useRef<HTMLDivElement>(null),trigger=useRef<HTMLButtonElement>(null),optionRefs=useRef<(HTMLDivElement|null)[]>([]);
 const selectedIndex=Math.max(0,options.findIndex(option=>option.value===value));
 useEffect(()=>{
  if(!open)return;
  const outside=(event:PointerEvent)=>{if(root.current&&!root.current.contains(event.target as Node))setOpen(false)};
  document.addEventListener("pointerdown",outside);
  return()=>document.removeEventListener("pointerdown",outside);
 },[open]);
 useEffect(()=>{if(open)optionRefs.current[focused]?.focus()},[open,focused]);
 const choose=(nextValue:string)=>{onChange(nextValue);setOpen(false);trigger.current?.focus()};
 const keys=(event:KeyboardEvent<HTMLDivElement>)=>{
  if(event.key==="Escape"&&open){event.preventDefault();event.stopPropagation();setOpen(false);trigger.current?.focus();return}
  if(event.key==="Tab"){setOpen(false);return}
  if(["ArrowDown","ArrowUp","Home","End"].includes(event.key)){
   event.preventDefault();
   let next=open?focused:selectedIndex;
   if(event.key==="ArrowDown")next=(next+1)%options.length;
   if(event.key==="ArrowUp")next=(next+options.length-1)%options.length;
   if(event.key==="Home")next=0;
   if(event.key==="End")next=options.length-1;
   setFocused(next);setOpen(true);return;
  }
  if(open&&(event.key==="Enter"||event.key===" ")&&event.target!==trigger.current){event.preventDefault();choose(options[focused].value)}
 };
 return <div className="bookingDropdownField"><span id={id+"-label"} className="bookingDropdownLabel">{label}</span><div className="bookingDropdown" ref={root} onKeyDown={keys} onBlur={event=>{if(!event.currentTarget.contains(event.relatedTarget))setOpen(false)}}>
  <button ref={trigger} id={id+"-trigger"} type="button" className={"bookingDropdownTrigger"+(open?" isOpen":"")} aria-labelledby={id+"-label "+id+"-trigger"} aria-haspopup="listbox" aria-controls={id+"-options"} aria-expanded={open} onClick={()=>{if(!open)setFocused(selectedIndex);setOpen(!open)}}><span>{options[selectedIndex]?.label||value}</span><ChevronDown size={16} aria-hidden="true"/></button>
  {open&&<div id={id+"-options"} className="bookingDropdownMenu" role="listbox" aria-labelledby={id+"-label"}>{options.map((option,index)=><div key={option.value} ref={element=>{optionRefs.current[index]=element}} role="option" tabIndex={focused===index?0:-1} aria-selected={value===option.value} className={"bookingDropdownOption"+(value===option.value?" isSelected":"")} onClick={()=>choose(option.value)} onMouseEnter={()=>setFocused(index)}><span>{option.label}</span><span className="bookingDropdownCheck" aria-hidden="true">{value===option.value?"✓":""}</span></div>)}</div>}
 </div></div>;
}

function TapeVideo({className,label}:{className:string;label?:string}){
 const ref=useRef<HTMLVideoElement>(null);
 useEffect(()=>{
  const v=ref.current;if(!v)return;
  let frame=0;
  const restart=()=>{
   if(v.seeking)return;
   try{v.currentTime=0;}catch{return;}
   if(v.paused)void v.play().catch(()=>{});
  };
  const check=()=>{
   if(v.readyState>=2&&Number.isFinite(v.duration)&&v.duration>1&&v.currentTime>=v.duration-0.5)restart();
   frame=requestAnimationFrame(check);
  };
  frame=requestAnimationFrame(check);
  v.addEventListener("ended",restart);
  return()=>{cancelAnimationFrame(frame);v.removeEventListener("ended",restart);};
 },[]);
 return <video ref={ref} className={className} src="/studio-video/Tape.mp4" autoPlay muted loop playsInline preload="auto" poster={img.film} aria-hidden={label?undefined:true} aria-label={label}/>;
}
