type Artist={id:string;name:string;image:string;title?:string;label?:string;contribution?:string;year?:string;description?:string;by?:string};
function ArtistStrip({lang}:{lang:Lang}){
 const router=useRouter();
 const [artists,setArtists]=useState<Artist[]>([]);
 const [selected,setSelected]=useState<Artist|null>(null);
 const track=useRef<HTMLDivElement|null>(null);
 const paused=useRef(false);const hovering=useRef(false);const dragging=useRef(false);const moved=useRef(false);
 const dragStart=useRef({x:0,scroll:0});
 useEffect(()=>{let alive=true;fetch("/api/artists",{cache:"no-store"}).then(r=>r.json()).then(data=>{if(alive&&Array.isArray(data.artists))setArtists(data.artists)}).catch(()=>{});return()=>{alive=false}},[]);
 useEffect(()=>{const el=track.current;if(!el||artists.length===0)return;let raf=0;let prev=0;
 const tick=(time:number)=>{if(prev===0)prev=time;const delta=Math.min(48,time-prev);prev=time;
 if(!paused.current&&!dragging.current){el.scrollLeft+=delta*.045;const half=el.scrollWidth/2;if(half>0&&el.scrollLeft>=half)el.scrollLeft-=half}
 raf=requestAnimationFrame(tick)};raf=requestAnimationFrame(tick);return()=>cancelAnimationFrame(raf)},[artists]);
 useEffect(()=>{if(!artists.length)return;const el=document.querySelector(".artistCreditsCallout.collabEnterRight");if(!el)return;const obs=new IntersectionObserver(entries=>{if(entries[0]?.isIntersecting){el.classList.add("shown");obs.disconnect()}},{threshold:.1});obs.observe(el);return()=>obs.disconnect()},[artists]);
 useEffect(()=>{if(!selected)return;const onKey=(e:KeyboardEvent)=>{if(e.key==="Escape")setSelected(null)};window.addEventListener("keydown",onKey);return()=>window.removeEventListener("keydown",onKey)},[selected]);
 const down=(e:React.PointerEvent<HTMLDivElement>)=>{if(e.pointerType==="mouse"&&e.button!==0)return;dragging.current=true;paused.current=true;moved.current=false;dragStart.current={x:e.clientX,scroll:track.current?.scrollLeft||0};e.currentTarget.setPointerCapture(e.pointerId)};
 const move=(e:React.PointerEvent<HTMLDivElement>)=>{if(!dragging.current||!track.current)return;const distance=e.clientX-dragStart.current.x;if(Math.abs(distance)>6)moved.current=true;track.current.scrollLeft=dragStart.current.scroll-distance;const half=track.current.scrollWidth/2;if(half>0){if(track.current.scrollLeft>=half){track.current.scrollLeft-=half;dragStart.current={x:e.clientX,scroll:track.current.scrollLeft}}}};
 const up=(e:React.PointerEvent<HTMLDivElement>)=>{dragging.current=false;if(e.currentTarget.hasPointerCapture(e.pointerId))e.currentTarget.releasePointerCapture(e.pointerId);paused.current=hovering.current;};
 if(!artists.length)return <section className="artistStripEmpty"><span>{lang==="de"?"ARTISTS & COLLABORATIONS":"ARTISTS & COLLABORATIONS"}</span><p>{lang==="de"?"Künstlerfotos werden aus public/images/artist/ geladen, sobald sie dort vorhanden sind.":"Artist portraits appear here once added to public/images/artist/."}</p></section>;
 return <section className="artistStrip" aria-label="Artists and collaborators">
  <div className="artistStripHeading"><small>{lang==="de"?"UNSERE ZUSAMMENARBEITEN":"OUR COLLABORATIONS"}</small><span>{lang==="de"?"ZIEHEN, ANHALTEN & ANKLICKEN":"DRAG, PAUSE & EXPLORE"}</span></div>
  <div className="artistTrack" ref={track} onPointerDown={down} onPointerMove={move} onPointerUp={up} onPointerCancel={up} onMouseEnter={()=>{hovering.current=true;paused.current=true}} onMouseLeave={()=>{hovering.current=false;if(!dragging.current)paused.current=false}}>
   {[...artists,...artists].map((artist,i)=><button type="button" draggable={false} className="artistTile" key={artist.id+"-"+i} onClick={()=>{if(!moved.current)setSelected(artist);moved.current=false}} aria-label={artist.name}>
     <img src={artist.image} alt={artist.name} draggable={false}/><span className="artistOverlay"><span className="artistMetaLabel">ARTIST</span><strong>{artist.name}</strong><span className="artistMetaLabel">TITLE</span><span className="artistMetaTitle">{artist.title||"—"}</span>{artist.label&&<><span className="artistMetaLabel">LABEL</span><span className="artistMetaTitle">{artist.label}</span></>}<span className="artistMetaDivider"/><span className="artistMetaLabel">WORK</span><span className="artistMetaRole">{artist.contribution||"—"}</span><span className="artistMetaLabel">CREDIT</span><span className="artistMetaBy">{(artist.by||"George Brasch").replace(/^by\s+/i,"")}</span></span>
    </button>)}
  </div>
  <div className="artistCreditsCallout collabEnterRight"><a href={"/"+lang+"/credits"} className="artistCreditsLink" onClick={e=>{if(e.button!==0||e.metaKey||e.ctrlKey||e.shiftKey||e.altKey)return;e.preventDefault();router.push("/"+lang+"/credits")}}><span>{lang==="de"?"ALLE CREDITS ENTDECKEN":"EXPLORE ALL CREDITS"}</span></a></div>
   {selected&&<div className="artistModalBackdrop" onMouseDown={e=>{if(e.target===e.currentTarget)setSelected(null)}}>
    <section className="artistModal" role="dialog" aria-modal="true" aria-label={selected.name}>
     <button className="artistModalClose" onClick={()=>setSelected(null)} aria-label="Close"><X/></button>
     <img src={selected.image} alt={selected.name}/><div><small>AMBER / ARTIST</small><h2>{selected.name}</h2>{selected.title&&<h3 className="artistModalTitle">{selected.title}</h3>}{selected.label&&<p className="artistModalCredit"><b>LABEL:</b> {selected.label}</p>}{selected.contribution&&<p className="artistModalCredit"><b>{lang==="de"?"MEIN BEITRAG":"MY CONTRIBUTION"}:</b> {selected.contribution}</p>}<p>{selected.description||(lang==="de"?"Weitere Informationen zu unserer Zusammenarbeit werden nach Prüfung der Credits ergänzt.":"Collaboration details will follow once the credits are verified.")}</p><button className="artistModalBack" onClick={()=>setSelected(null)}>{lang==="de"?"SCHLIESSEN":"CLOSE"}</button></div>
    </section>
  </div>}
 </section>
}

type CoversResponse={covers:Record<string,string>;entries:SelectedEntry[]};
let sharedCovers:CoversResponse|null=null;
let pendingCovers:Promise<CoversResponse>|null=null;
let prewarmedCovers=false;
function getSharedCovers(refresh=false):Promise<CoversResponse>{
 if(!refresh&&sharedCovers)return Promise.resolve(sharedCovers);
 if(refresh)pendingCovers=null;
 if(!pendingCovers)pendingCovers=fetch("/api/selected-covers",{cache:"no-store"}).then(r=>{if(!r.ok)throw Error("Covers unavailable");return r.json()}).then((data:CoversResponse)=>{sharedCovers={covers:data.covers||{},entries:data.entries||[]};return sharedCovers}).catch(e=>{pendingCovers=null;throw e});
 return pendingCovers;
}
function warmCoverImages(entries:SelectedEntry[]){
 if(prewarmedCovers||typeof window==="undefined")return;
 prewarmedCovers=true;
 let next=0;
 const loadNext=()=>{if(next>=entries.length)return;const image=new Image();image.decoding="async";image.onload=loadNext;image.onerror=loadNext;image.src=entries[next++].image;};
 for(let i=0;i<3;i++)loadNext();
}

