 <header className={`header${current===""?" headerOverHero":""}`}> <a className="logo" aria-label="AMBER Recording Studio Berlin — home" href={url("")} onClick={e=>{e.preventDefault();go("")}}><svg className="amberWordmark" viewBox="0 0 224 66" role="img" aria-hidden="true"><text x="0" y="45" textLength="224" lengthAdjust="spacingAndGlyphs">AMBER<tspan fill="#d8aa62">.</tspan></text><text className="amberSubtitle" x="0" y="64" textLength="224" lengthAdjust="spacingAndGlyphs">RECORDING STUDIO <tspan fill="#d8aa62">BERLIN</tspan></text></svg></a><nav className="nav">{paths.slice(0,7).map((s,i)=><a key={s} className={current===s?"active":""} href={url(s)} onClick={e=>{e.preventDefault();go(s)}}>{t.nav[i]}</a>)}</nav><div className="headerActions"><button className="language" aria-label={lang==="en"?"Switch to German":"Switch to English"} onClick={()=>router.push(url(current,lang==="en"?"de":"en"))}>{lang==="en"?"DE":"EN"}</button><a className="headerBook" href={url("booking")} onClick={e=>{e.preventDefault();go("booking")}}>{t.nav[8]}</a><button className="menuButton" aria-label={menu?"Close navigation":"Open navigation"} aria-expanded={menu} onClick={()=>setMenu(!menu)}>{menu?<X/>:<Menu/>}</button></div></header>
